// ===== Code in JavaScript2 : validate 2 images + build Gemini request =====
// แอป (artwork_check/pairdiff.py) ส่ง POST form-urlencoded 2 ฟิลด์:
//   image_a_b64 = ภาพโซนของไฟล์หลัก (🅰) · image_b_b64 = ภาพโซนของไฟล์อ้างอิง (🅱)
// โหนดนี้ตรวจ base64/ชนิดภาพ แล้วประกอบ request ของ Gemini (temperature = 0)

const item = $input.first().json;
const body = item.body ?? item;

function clean(v) {
  let b64 = String(v ?? '').trim();
  const m = b64.match(/^data:image\/[a-z0-9.+-]+;base64,(.+)$/is);
  if (m) b64 = m[1];
  return b64.replace(/\s+/g, '').replace(/ /g, '+');
}
function mimeOf(b64) {
  const h = Buffer.from(b64.slice(0, 32), 'base64');
  if (h[0] === 0x89 && h[1] === 0x50 && h[2] === 0x4e) return 'image/png';
  if (h[0] === 0xff && h[1] === 0xd8) return 'image/jpeg';
  if (h[0] === 0x52 && h[1] === 0x49 && h[2] === 0x46 && h[8] === 0x57 && h[9] === 0x45) return 'image/webp';
  return null;
}

const a = clean(body.image_a_b64);
const b = clean(body.image_b_b64);
let valid = true;
let error = '';
const re64 = /^[A-Za-z0-9+/]+={0,2}$/;
for (const [name, v] of [['image_a_b64', a], ['image_b_b64', b]]) {
  if (!v) { valid = false; error = `missing form field '${name}'`; break; }
  if (v.length % 4 !== 0 || !re64.test(v)) { valid = false; error = `'${name}' is not valid base64`; break; }
}
const mimeA = valid ? mimeOf(a) : null;
const mimeB = valid ? mimeOf(b) : null;
if (valid && (!mimeA || !mimeB)) { valid = false; error = 'unsupported image format (expected JPEG / PNG / WebP)'; }
const sizeBytes = Math.floor((a.length + b.length) * 3 / 4);
if (valid && sizeBytes > 19 * 1024 * 1024) {
  valid = false;
  error = `images too large: ${(sizeBytes / 1048576).toFixed(1)} MB (limit ~19 MB)`;
}

const PROMPT = "You compare two images of the SAME printed label panel.\nIMAGE A = the approved artwork (reference design, usually a clean PDF render).\nIMAGE B = the version to check (a proof or a PHOTO of the printed pack; may have glare, perspective, texture).\n\nSTEP 1 - Transcribe EACH image INDEPENDENTLY and VERBATIM.\n- Read the characters of B from B's pixels only. NEVER copy text from A into B (or B into A).\n  Use the other image only to help you locate text, never to decide which characters are printed.\n- If B prints something different from A, b_text MUST show what B actually prints.\n- DO NOT correct spelling, grammar, punctuation, digits or units. Preserve decimal points,\n  minus signs, <, >, %, superscripts and symbols (e.g. \"0.5g\", \"<1g\", \"-18°C\", \"®\").\n- One text element per line, reading order top-to-bottom, left-to-right.\n- Text on curves/badges: transcribe it when legible.\n\nSTEP 2 - List EVERY difference between what A prints and what B prints.\n- Report ALL differences, including a single character, a digit, a decimal point, a sign,\n  letter case, a missing or extra word or line. Do not stop after a few.\n- \"a\" and \"b\": quote the differing text EXACTLY as it appears in your a_text / b_text\n  (shortest span that shows the difference, e.g. a=\"1g\" b=\"7g\"). Use \"\" when absent on that side.\n- kind: \"number\" if digits/units/decimals/signs are involved, \"text\" for words/letters/\n  punctuation, \"visual\" for non-text differences (font weight, colour, logo, symbol, barcode\n  bars, layout) - for visual use a=\"\" b=\"\" and describe it in \"where\".\n- \"where\": short location hint (e.g. \"Total Fat row\", \"2nd paragraph\").\n- DO NOT report differences caused only by line wrapping, image quality, glare, perspective,\n  resolution, or the part of the image outside the label panel.\n- If the two panels are identical, return an empty differences array.\n\nReturn ONLY JSON matching the schema.";

const responseSchema = {
  type: 'OBJECT',
  properties: {
    a_text: { type: 'STRING' },
    b_text: { type: 'STRING' },
    differences: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          a: { type: 'STRING' },
          b: { type: 'STRING' },
          kind: { type: 'STRING', enum: ['text', 'number', 'visual'] },
          where: { type: 'STRING' },
        },
        required: ['a', 'b', 'kind'],
      },
    },
  },
  // ถอดความ "ก่อน" เทียบ — โมเดลเขียนตามลำดับนี้
  propertyOrdering: ['a_text', 'b_text', 'differences'],
  required: ['a_text', 'b_text', 'differences'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT },
      { text: 'IMAGE A (approved artwork):' },
      { inlineData: { mimeType: mimeA, data: a } },
      { text: 'IMAGE B (version to check):' },
      { inlineData: { mimeType: mimeB, data: b } },
    ],
  }],
  generationConfig: {
    temperature: 0,          // ห้ามแก้ — ต้องวัดซ้ำได้
    topP: 1,
    maxOutputTokens: 24576,
    responseMimeType: 'application/json',
    responseSchema,
    // งานเทียบต้อง "คิด" มากกว่างานถอดความ — ให้งบคิดพอประมาณ
    // (ตั้ง 0 = เร็วขึ้นแต่อาจพลาดความต่าง · ลบบรรทัดนี้ถ้ารุ่นที่ใช้ไม่รองรับ)
    thinkingConfig: { thinkingBudget: 1024 },
  },
};

return [{ json: { valid, error, size_kb: Math.round(sizeBytes / 102.4) / 10, gemini_request: geminiRequest } }];

// ===== Code in JavaScript : parse Gemini response → app contract =====
// แอปคาดหวัง: {"a_text": "...", "b_text": "...", "differences": [...], "engine": "..."}
// ⚠️ ห้ามคืนคำตอบว่าง — แอปถือว่า "ว่าง = ล้มเหลว" แล้วยิงซ้ำ
const r = $input.first().json;
if (r.error) {
  throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);
}
const cand = (r.candidates ?? [])[0] ?? {};
const finishReason = cand.finishReason ?? '';
const raw = ((cand.content ?? {}).parts ?? []).map((p) => p.text ?? '').join('\n').trim();
let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(s); } catch (e) {
  const i = s.indexOf('{'); const j = s.lastIndexOf('}');
  if (i >= 0 && j > i) { try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) { /* noop */ } }
}
const out = { a_text: '', b_text: '', differences: [], engine: 'gemini-2.5-flash' };
if (parsed && typeof parsed === 'object') {
  out.a_text = typeof parsed.a_text === 'string' ? parsed.a_text : '';
  out.b_text = typeof parsed.b_text === 'string' ? parsed.b_text : '';
  out.differences = Array.isArray(parsed.differences) ? parsed.differences : [];
}
if (!out.a_text || !out.b_text) {
  out.error = `incomplete answer (finishReason=${finishReason || 'unknown'})`;
}
if (finishReason && finishReason !== 'STOP') {
  out.warning = `finishReason=${finishReason}`;
}
out.usage = r.usageMetadata ?? null;
return [{ json: out }];
